// Parser robusto del output JSON del Agente Laundry VIP
// Tolerante a: comillas curvas, BOM, fences ```json, múltiples JSON pegados, NBSP

const rawOutput = $input.first().json.output || '';
const waInicio = $('WhatsApp Inicio').first().json;

function tryParseLLMOutput(s) {
  if (typeof s !== 'string') return s;
  let t = s
    .replace(/^\uFEFF/, '')                          // BOM
    .replace(/^\s*```(?:json)?\s*/i, '')             // fence apertura
    .replace(/\s*```\s*$/i, '')                      // fence cierre
    .replace(/[\u201C\u201D]/g, '"')                 // comillas curvas dobles -> "
    .replace(/[\u2018\u2019]/g, "'")                 // comillas curvas simples -> '
    .replace(/\u00A0/g, ' ');                        // nbsp -> espacio
  // Si hay multiples JSON pegados, quedate con el primer objeto balanceado
  const start = t.indexOf('{');
  if (start === -1) throw new Error('no JSON found');
  let depth = 0, end = -1, inStr = false, esc = false;
  for (let i = start; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
    } else {
      if (c === '"') inStr = true;
      else if (c === '{') depth++;
      else if (c === '}') { depth--; if (depth === 0) { end = i; break; } }
    }
  }
  if (end === -1) throw new Error('unbalanced JSON');
  return JSON.parse(t.slice(start, end + 1));
}

let parsed = {};
let parseFailed = false;
try {
  parsed = typeof rawOutput === 'string' ? tryParseLLMOutput(rawOutput) : rawOutput;
} catch(e) {
  // Fallback FINAL: NUNCA mandar JSON crudo. Mensaje de cortesia + escalar humano.
  parseFailed = true;
  parsed = {
    respuesta_lead: 'Permítame un momento, le contacta una persona de nuestro equipo.',
    tool_consultada: null,
    imagenes: [],
    videos: [],
    ubicacion: false,
    escalar_humano: true,
    metadata: {
      temperatura: 'tibio',
      pain_point: 'parser fallo, escalar a humano',
      objeciones: [],
      next_action: 'esperar_respuesta',
      quality_score: 0,
      tipo_lead: 'otro',
      datos_lead: {}
    }
  };
}


// ── Guardia anti-alucinación ─────────────────────────────────────────────
// El modelo puede escribir "✅ Orden registrada" con un ID inventado sin haber
// llamado a la herramienta. Solo vale lo que la herramienta devolvió ok:true
// en ESTE turno; un UUID que no salió de una herramienta es inventado.
const pasos = Array.isArray($input.first().json.intermediateSteps) ? $input.first().json.intermediateSteps : [];
const ESCRITURAS = ['registrar_cliente_presencial', 'actualizar_registro', 'avanzar_estado', 'registrar_conteo', 'crear_pedido'];
const observaciones = pasos.map((p) => String((p && p.observation) || '')).join(' ');
const escriturasOk = pasos.filter((p) => p && p.action && ESCRITURAS.includes(p.action.tool) && /"ok"\s*:\s*true/.test(String(p.observation || '')));
const textoModelo = String(parsed.respuesta_lead || '');
const uuids = textoModelo.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi) || [];
const idInventado = uuids.some((id) => !observaciones.includes(id));
const escrituraFantasma = ESCRITURAS.includes(parsed.tool_consultada) && escriturasOk.length === 0;
let esOperadorGuardia = false;
try { esOperadorGuardia = $('Verificar Operador').first().json.data?.es_operador === true; } catch (e) {}
const confirmacionFalsa = !parseFailed && (idInventado || escrituraFantasma);
// ── Guardia de valores sin herramienta ───────────────────────────────────
// Un modelo (Gemini flash-lite en la prueba del 2026-10-09) respondió «$31,50» y «48 horas»
// sin llamar a ninguna herramienta y marcó tool_consultada «cotizar_prendas». Un monto o un
// plazo solo vale si salió de una herramienta de precios en ESTE turno o ya se le había dicho
// al cliente antes; si no, se reemplaza y una persona confirma.
const PRECIOS = ['cotizar_prendas', 'obtener_proxima_ventana', 'consultar_estado_pedido'];
const usoPrecios = pasos.some((p) => p && p.action && PRECIOS.includes(p.action.tool));
let dichoAntes = '';
try { dichoAntes = (($('Obtener Ultimos Mensajes').first().json.payload) || []).filter((m) => m.message_type === 1).map((m) => String(m.content || '')).join(' '); } catch (e) {}
const montos = textoModelo.match(/\$\s?\d+(?:[.,]\d+)?/g) || [];
const plazos = textoModelo.match(/\d+\s*horas/gi) || [];
const aCentavos = (t) => Math.round(Number(String(t).replace(/[^0-9.,]/g, '').replace(',', '.')) * 100);
const dados = [...new Set([...(dichoAntes.match(/\$\s?\d+(?:[.,]\d+)?/g) || []), ...(observaciones.match(/\d+(?:\.\d+)?/g) || [])].map(aCentavos).filter((n) => Number.isFinite(n) && n > 0))].slice(0, 14);
// Un total armado con cifras que ya salieron (subtotal + tarifa, 2 x precio...) tampoco es inventado.
let validos = new Set(dados);
for (let ronda = 0; ronda < 3; ronda++) { const nuevos = new Set(validos); for (const a of validos) for (const b of dados) nuevos.add(a + b); validos = nuevos; }
const sinFuente = (t) => !dichoAntes.replace(/\s/g, '').includes(t.replace(/\s/g, '')) && !validos.has(aCentavos(t));
const valorSinHerramienta = !parseFailed && !esOperadorGuardia && !usoPrecios && [...montos, ...plazos].some(sinFuente);
if (valorSinHerramienta) {
  parsed.respuesta_lead = 'Permítame confirmarle ese valor con una persona de nuestro equipo y le escribe en breve.';
  parsed.escalar_humano = true;
}
if (confirmacionFalsa) {
  parsed.respuesta_lead = esOperadorGuardia
    ? '⚠️ La orden NO quedó registrada: no llegué a guardarla en el sistema. Responde «registrar» y la guardo ahora con los mismos datos.'
    : 'Disculpe, no pude completar el registro en este momento. Una persona de nuestro equipo lo revisa y le confirma en breve.';
  if (!esOperadorGuardia) parsed.escalar_humano = true;
}

const imagenes = Array.isArray(parsed.imagenes) ? parsed.imagenes : [];
const videos = Array.isArray(parsed.videos) ? parsed.videos : [];
const metadata = parsed.metadata || {};
const datosLead = metadata.datos_lead || {};

return [{
  json: {
    // Texto limpio que se enviara al lead (sin metadata, sin markers)
    texto_limpio: parsed.respuesta_lead || '',

    // Imagenes (hasta 5) para los nodos Enviar Img 1-5
    img1: imagenes[0] || '',
    img2: imagenes[1] || '',
    img3: imagenes[2] || '',
    img4: imagenes[3] || '',
    img5: imagenes[4] || '',

    // Videos (hasta 2) para los nodos Enviar Video
    vid1: videos[0] || '',
    vid2: videos[1] || '',

    // Markers de comportamiento
    ubicacion: parsed.ubicacion === true ? 'si' : '',
    escalar_humano: parsed.escalar_humano === true ? 'si' : '',

    // Datos del flow (no cambian)
    phone: waInicio.contacts[0].wa_id,
    conv_id: waInicio._chatwoot_conversation_id,

    // Flag de parser para diagnostico
    parser_failed: parseFailed,
    confirmacion_falsa: confirmacionFalsa,
    valor_sin_herramienta: valorSinHerramienta,

    // Metadata para CRM / logging
    metadata_temperatura: metadata.temperatura || 'frio',
    metadata_pain_point: metadata.pain_point || '',
    metadata_objeciones: Array.isArray(metadata.objeciones) ? metadata.objeciones.join(', ') : '',
    metadata_next_action: metadata.next_action || 'esperar_respuesta',
    metadata_quality_score: metadata.quality_score || 0,
    metadata_tipo_lead: metadata.tipo_lead || 'otro',
    metadata_tool_consultada: parsed.tool_consultada || null,

    // Datos del lead (estructurados)
    lead_nombre: datosLead.nombre || null,
    lead_servicio: datosLead.servicio || null,
    lead_ubicacion: datosLead.ubicacion || null,
    lead_metros: datosLead.metros || null,
    lead_nivel_acabado: datosLead.nivel_acabado || null,
    lead_presupuesto_usd: datosLead.presupuesto_usd || null,
    lead_timeline: datosLead.timeline || null,
    lead_tiene_terreno: datosLead.tiene_terreno || null,

    // Cotizacion (mantenido por compatibilidad - vacio por ahora)
    cotizacion_json: ''
  }
}];

// Arma lo que se registra en el CRM de Lavandería VIP en cada turno.
// El nombre del perfil de WhatsApp entra como provisional; el que diga el cliente lo reemplaza.
const wa = $('WhatsApp Inicio').first().json;
const ext = $('Extraer JSON').first().json;
const msg = $('Preparar Mensaje Final').first().json;

// Un operador de planta no es un lead: sus órdenes ya quedan en el CRM por sus tools.
let esOperador = false;
try { esOperador = $('Verificar Operador').first().json.data?.es_operador === true; } catch (e) {}
if (esOperador) return [];

const telefono = '+' + String(wa.contacts[0].wa_id || '').replace(/\D/g, '');
const perfil = (wa.contacts[0].profile && wa.contacts[0].profile.name) || '';
const nombre = ext.lead_nombre && ext.lead_nombre !== perfil ? String(ext.lead_nombre) : '';
const tipo = ['clinica', 'restaurante', 'hotel'].includes(ext.metadata_tipo_lead) ? ext.metadata_tipo_lead : null;
const convId = Number(wa._chatwoot_conversation_id) || null;

const clienteParams = { telefono, canal_origen: 'whatsapp_agente' };
if (perfil) clienteParams.nombre_whatsapp = perfil;
if (nombre) clienteParams.nombre_contacto = nombre;
if (tipo) clienteParams.tipo_negocio = tipo;

const conversacionParams = {
  telefono,
  contexto: {
    nombre_whatsapp: perfil,
    temperatura: ext.metadata_temperatura || '',
    necesidad: ext.metadata_pain_point || '',
    proxima_accion: ext.metadata_next_action || '',
    ultimo_mensaje_cliente: String(msg.message_text || '').slice(0, 500),
    ultima_respuesta_agente: String(ext.texto_limpio || '').slice(0, 500),
    escalado: ext.escalar_humano === 'si',
    tool_consultada: ext.metadata_tool_consultada || null,
    chatwoot_url: convId ? 'https://chatwoot-production-8564.up.railway.app/app/accounts/3/conversations/' + convId : '',
  },
};
if (convId) conversacionParams.chatwoot_conversation_id = convId;

return [{ json: {
  cliente: { accion: 'find_or_create_client', parametros: clienteParams },
  conversacion: { accion: 'sincronizar_memoria_conversacion', parametros: conversacionParams },
} }];

// Un mensaje por administrador: texto libre y, por si está fuera de las 24 h,
// los 7 datos que pide la plantilla.
const r = $input.first().json.data || {};
const dinero = (n) => '$' + Number(n || 0).toFixed(2).replace('.', ',');
return (r.admins || []).map((admin) => {
  const nombre = String(admin.nombre || 'equipo').split(' ')[0];
  const ventas = dinero(r.ventas_verificadas_ayer) + ' en ' + (r.pedidos_ayer || 0) + ' pedidos';
  return {
    json: {
      telefono: String(admin.telefono || '').replace(/\D/g, ''),
      dentro_de_ventana: admin.dentro_de_ventana === true,
      texto: [
        'Buenos días, ' + nombre + '. Resumen de hoy, ' + (r.fecha || '') + ':',
        '• Ventas verificadas ayer: ' + ventas,
        '• Recolecciones hoy: ' + (r.recolecciones_hoy || 0),
        '• Discrepancias abiertas: ' + (r.discrepancias_abiertas || 0),
        '• Pagos pendientes: ' + (r.pagos_pendientes || 0),
        '• Recolectados sin contar: ' + (r.sin_contar_en_planta || 0),
        '• Leads calientes sin pedido: ' + (r.leads_calientes_sin_pedido || 0),
        'Detalle en el CRM: https://laundry-vip.vercel.app',
      ].join('\n'),
      parametros: [
        nombre,
        r.fecha || '',
        ventas,
        String(r.recolecciones_hoy || 0),
        String(r.discrepancias_abiertas || 0),
        String(r.pagos_pendientes || 0),
        String(r.leads_calientes_sin_pedido || 0),
      ],
    },
  };
});

