// Chatwoot y WhatsApp deciden cómo mostrarlo por el nombre y el tipo del archivo.
const it = $input.first();
it.binary.data.fileName = 'catalogo.png';
it.binary.data.mimeType = 'image/png';
return [{ json: it.json, binary: it.binary }];

// Un mensaje por aviso y por persona del equipo.
const r = $input.first().json || {};
const d = r.data || {};
const out = [];
for (const a of d.avisos || []) {
  for (const p of d.destinatarios || []) {
    out.push({ json: { aviso_id: a.id, texto: a.texto, parametros: a.parametros, telefono: p.telefono, dentro_de_ventana: p.dentro_de_ventana } });
  }
}
return out;

// Un elemento por aviso, para marcarlo una vez entregado.
const d = ($input.first().json || {}).data || {};
return (d.avisos || []).map((a) => ({ json: { id: a.id, estado: a.reintento ? 'reintentado' : 'enviado' } }));
